<?php

declare(strict_types=1);

namespace App\Admin\Infrastructure;

/**
 * Seed figée dans le code de migration : un nouvel environnement ne dépend jamais d'un YAML
 * ou d'une traduction déjà retirés du dépôt. Le blob est du JSON normalisé encodé pour garder
 * la migration lisible sans introduire un second format de configuration exécutable.
 */
final class GameRulesetSeed
{
    private const string DATA = '';

    /** @return array<string, mixed> */
    public static function data(): array
    {
        $json = base64_decode(self::DATA, true);
        \assert(false !== $json);
        $data = json_decode($json, true, 512, \JSON_THROW_ON_ERROR);
        \assert(\is_array($data));
        /** @var array<string, mixed> $data */
        require_once \dirname(__DIR__, 3).'/migrations/GameBalanceSeed.php';
        /** @var array<string, mixed> $balance */
        $balance = \DoctrineMigrations\GameBalanceSeed::data();

        return [...$data, ...$balance];
    }
}
